          "picture": null
        },
        {
          "text": "2, 3, 4, 5, 6",
          "isCorrect": false,
          "reason": "Including 6 is a common slip, but Python leaves out the stop number, so 6 does not print.",
          "picture": null
        },
        {
          "text": "3, 4, 5, 6",
          "isCorrect": false,
          "reason": "Python starts right at the first number, 2, and leaves out the stop number, 6.",
          "picture": null
        },
        {
          "text": "2, 3, 4",
          "isCorrect": false,
          "reason": "That stops too early. Counting from 2 up to but not including 6 gives four numbers, ending at 5.",
          "picture": null
        }
      ],
      "image": null,
      "visual": null,
      "basis": {
        "screen": 2,
        "quote": "With **range(start, stop)**, counting begins at `start` and always leaves out `stop`."
      }
    },
